import type { ConcreteSongLanguage } from "../planning-lifecycle";

export type ReferenceCatalogLanguageFilter = ConcreteSongLanguage | "all";
export type ReferenceCatalogRecord = { id: string; language: ConcreteSongLanguage; canonicalNumber: number; displayNumber: string; title: string; sourceUrl?: string };
export type ReferenceCatalogQuery = { language?: ReferenceCatalogLanguageFilter; search?: string; page?: number; pageSize?: number };
export type ReferenceCatalogPage = { records: ReferenceCatalogRecord[]; total: number; page: number; pageSize: number; pageCount: number; counts: { all: number; czech: number; polish: number } };

export function displayReferenceNumber(encoded: number): string {
  if (!Number.isInteger(encoded) || encoded <= 0) throw new Error("Reference catalog number must be a positive integer.");
  if (encoded < 1000) return String(encoded);
  if (encoded % 10 !== 0) return `${Math.floor(encoded / 10)}/${encoded % 10}`;
  if (encoded % 100 !== 0) return `${Math.floor(encoded / 100)}/${Math.floor(encoded / 10) % 10}`;
  if (encoded % 1000 !== 0) return `${Math.floor(encoded / 1000)}/${Math.floor(encoded / 100) % 10}`;
  return String(encoded);
}

export function normalizeReferenceNumberQuery(query: string): number | undefined {
  const trimmed = query.trim();
  if (/^[1-9]\d*$/.test(trimmed)) return Number(trimmed);
  const slash = trimmed.match(/^([1-9]\d*)\/([1-8])$/);
  if (!slash) return undefined;
  const base = Number(slash[1]); const variant = Number(slash[2]);
  if (base < 10) return base * 1000 + variant * 100;
  if (base < 100) return base * 100 + variant * 10;
  if (base < 1000) return base * 10 + variant;
  return undefined;
}

export function referenceNumberParts(encoded: number): { base: number; variant: number } {
  const [base, variant] = displayReferenceNumber(encoded).split("/").map(Number);
  return { base, variant: variant ?? 0 };
}

export function compareReferenceCatalogRecords(a: ReferenceCatalogRecord, b: ReferenceCatalogRecord): number {
  const an = referenceNumberParts(a.canonicalNumber); const bn = referenceNumberParts(b.canonicalNumber);
  return an.base - bn.base || an.variant - bn.variant || a.language.localeCompare(b.language) || a.title.localeCompare(b.title) || a.id.localeCompare(b.id);
}

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import type { Pool, PoolClient } from "pg";
import { recomputeReferenceMelodyPartition } from "./reference-melody-edge";

type InputRecord = { source_id?: unknown; language: unknown; number: unknown; title: unknown; source_url: unknown };
export type PersistedReferenceCatalogRecord = { id: string; language: "czech" | "polish"; canonicalNumber: number; sourceId: string; title: string; sourceUrl: string | null };

async function readFinalCatalog(path: string): Promise<unknown> {
  return JSON.parse(await readFile(resolve(process.cwd(), path), "utf8"));
}

export async function loadAndValidateReferenceCatalog(): Promise<PersistedReferenceCatalogRecord[]> {
  const inputs = await Promise.all([
    readFinalCatalog("data/catalog/catalog-czech-final.json"),
    readFinalCatalog("data/catalog/catalog-polish-final.json"),
  ]);
  if (!inputs.every(Array.isArray)) throw new Error("Authoritative reference catalogs must be JSON arrays.");
  const ids = new Set<string>(); const numbers = new Set<string>(); const sources = new Set<string>();
  const records = (inputs.flat() as InputRecord[]).map((raw) => {
    if ((raw.language !== "czech" && raw.language !== "polish") || !Number.isInteger(raw.number) || Number(raw.number) <= 0 || typeof raw.title !== "string" || !raw.title.trim() || (raw.source_url !== null && (typeof raw.source_url !== "string" || !raw.source_url.trim()))) throw new Error("Invalid authoritative reference catalog record.");
    const language = raw.language as "czech" | "polish"; const canonicalNumber = Number(raw.number); const id = `${language}:${canonicalNumber}`;
    let sourceId: string;
    if (language === "czech") {
      if (raw.source_id !== null && (typeof raw.source_id !== "string" || !raw.source_id.trim())) throw new Error("Czech reference source_id must be non-empty when supplied.");
      // Seven accepted Czech records have no upstream identity; their accepted catalog number is the only stable source token.
      sourceId = typeof raw.source_id === "string" ? raw.source_id : String(canonicalNumber);
    } else {
      if (typeof raw.source_url !== "string") throw new Error("Polish reference records require a Hymnary source URL.");
      const match = raw.source_url.match(/^https:\/\/hymnary\.org\/hymn\/SE2002\/([^/?#]+)$/);
      if (!match?.[1]) throw new Error("Polish reference source_id must be derived from the terminal Hymnary URL token.");
      sourceId = match[1];
    }
    const numberKey = `${language}:${canonicalNumber}`; const sourceKey = `${language}:${sourceId}`;
    if (ids.has(id) || numbers.has(numberKey) || sources.has(sourceKey)) throw new Error("Duplicate authoritative reference catalog identity.");
    ids.add(id); numbers.add(numberKey); sources.add(sourceKey);
    return { id, language, canonicalNumber, sourceId, title: raw.title, sourceUrl: raw.source_url as string | null };
  });
  const czech = records.filter((record) => record.language === "czech").length;
  const polish = records.filter((record) => record.language === "polish").length;
  if (czech !== 808 || polish !== 990 || records.length !== 1798) throw new Error(`Unexpected authoritative reference catalog counts: ${czech} / ${polish} / ${records.length}.`);
  return records;
}

export type ReferenceCatalogReconcileOptions = {
  failBeforeCommit?: boolean;
  /** Acceptance-only seam: callers may reconcile a derived catalog without changing frozen JSON. */
  records?: PersistedReferenceCatalogRecord[];
  expectedCounts?: { czech: number; polish: number; total: number };
};
export async function synchronizeReferenceCatalog(pool: Pool, options: ReferenceCatalogReconcileOptions = {}): Promise<{ czech: number; polish: number; total: number }> {
  const records = options.records ?? await loadAndValidateReferenceCatalog();
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query("CREATE TEMP TABLE incoming_reference_catalog (LIKE reference_catalog_songs INCLUDING DEFAULTS) ON COMMIT DROP");
    const values: unknown[] = []; const tuples: string[] = [];
    for (const record of records) {
      const offset = values.length;
      values.push(record.id, record.language, record.canonicalNumber, record.sourceId, record.title, record.sourceUrl);
      tuples.push(`($${offset + 1}, $${offset + 2}, $${offset + 3}, $${offset + 4}, $${offset + 5}, $${offset + 6})`);
    }
    await client.query(`INSERT INTO incoming_reference_catalog (id, language, canonical_number, source_id, title, source_url) VALUES ${tuples.join(",")}`, values);
    await client.query(`INSERT INTO reference_catalog_songs (id, language, canonical_number, source_id, title, source_url)
      SELECT id,language,canonical_number,source_id,title,source_url FROM incoming_reference_catalog
      ON CONFLICT (id) DO UPDATE SET language=excluded.language,canonical_number=excluded.canonical_number,source_id=excluded.source_id,title=excluded.title,source_url=excluded.source_url`);
    await client.query("INSERT INTO reference_melody_classes(id) SELECT 'reference-melody:'||i.id FROM incoming_reference_catalog i LEFT JOIN reference_song_melody_memberships m ON m.reference_song_id=i.id WHERE m.reference_song_id IS NULL ON CONFLICT DO NOTHING");
    await client.query("INSERT INTO reference_song_melody_memberships(reference_song_id,class_id) SELECT i.id,'reference-melody:'||i.id FROM incoming_reference_catalog i LEFT JOIN reference_song_melody_memberships m ON m.reference_song_id=i.id WHERE m.reference_song_id IS NULL ON CONFLICT DO NOTHING");
    await client.query("DELETE FROM reference_catalog_songs s WHERE NOT EXISTS (SELECT 1 FROM incoming_reference_catalog i WHERE i.id=s.id)");
    await client.query("DELETE FROM reference_melody_classes c WHERE NOT EXISTS (SELECT 1 FROM reference_song_melody_memberships m WHERE m.class_id=c.id)");
    await recomputeReferenceMelodyPartition(client);
    if (options.failBeforeCommit) throw new Error("Injected reference catalog synchronization failure.");
    const counts = await databaseReferenceCatalogCounts(client);
    const expected = options.expectedCounts ?? { czech: 808, polish: 990, total: 1798 };
    if (counts.czech !== expected.czech || counts.polish !== expected.polish || counts.total !== expected.total) throw new Error("Synchronized reference catalog counts are invalid.");
    await client.query("COMMIT");
    return counts;
  } catch (error) { await client.query("ROLLBACK").catch(() => undefined); throw error; }
  finally { client.release(); }
}

export async function databaseReferenceCatalogCounts(client: Pick<PoolClient, "query">): Promise<{ czech: number; polish: number; total: number }> {
  const result = await client.query("SELECT language, count(*)::integer AS count FROM reference_catalog_songs GROUP BY language");
  const count = (language: string) => Number(result.rows.find((row) => row.language === language)?.count ?? 0);
  const czech = count("czech"); const polish = count("polish");
  return { czech, polish, total: czech + polish };
}

import czechCatalog from "../../data/catalog/catalog-czech-final.json";
import polishCatalog from "../../data/catalog/catalog-polish-final.json";
import type { ConcreteSongLanguage } from "../planning-lifecycle";
import { compareReferenceCatalogRecords, displayReferenceNumber, normalizeReferenceNumberQuery, referenceNumberParts, type ReferenceCatalogPage, type ReferenceCatalogQuery, type ReferenceCatalogRecord } from "./reference-catalog-contract";
export * from "./reference-catalog-contract";
type RawReferenceCatalogRecord = { language: unknown; number: unknown; title: unknown; source_url: unknown };

export function createReferenceCatalogRecords(rawRecords: RawReferenceCatalogRecord[]): ReferenceCatalogRecord[] {
  return rawRecords.map((record) => {
    if ((record.language !== "czech" && record.language !== "polish") || !Number.isInteger(record.number) || typeof record.title !== "string" || !record.title.trim()) throw new Error("Invalid frozen reference catalog record.");
    const language = record.language as ConcreteSongLanguage;
    const canonicalNumber = record.number as number;
    const title = record.title as string;
    const sourceUrl = record.source_url === null ? undefined : record.source_url;
    if (sourceUrl !== undefined && typeof sourceUrl !== "string") throw new Error("Invalid reference catalog source URL.");
    return { id: `${language}:${canonicalNumber}`, language, canonicalNumber, displayNumber: displayReferenceNumber(canonicalNumber), title, ...(sourceUrl ? { sourceUrl } : {}) };
  }).sort(compareReferenceCatalogRecords);
}

function matchesReferenceNumber(record: ReferenceCatalogRecord, query: string): boolean {
  if (/^[1-9]\d{3,}$/.test(query)) return record.canonicalNumber === Number(query);
  const family = query.match(/^([1-9]\d*)\/?$/);
  if (family) {
    const { base, variant } = referenceNumberParts(record.canonicalNumber);
    return base === Number(family[1]) && (query.endsWith("/") ? variant > 0 : true);
  }
  const canonical = normalizeReferenceNumberQuery(query);
  return canonical !== undefined && record.canonicalNumber === canonical;
}

export class InMemoryReferenceCatalogProvider {
  private readonly records: ReferenceCatalogRecord[];
  readonly counts: ReferenceCatalogPage["counts"];
  constructor(records: ReferenceCatalogRecord[] = referenceCatalogRecords) {
    this.records = [...records].sort(compareReferenceCatalogRecords);
    this.counts = { all: this.records.length, czech: this.records.filter((r) => r.language === "czech").length, polish: this.records.filter((r) => r.language === "polish").length };
  }
  list(input: ReferenceCatalogQuery = {}): ReferenceCatalogPage {
    const language = input.language ?? "all";
    const search = input.search?.trim() ?? "";
    const isNumberQuery = /^[1-9]\d*(?:\/[1-8]?)?$/.test(search);
    const titleQuery = search.toLocaleLowerCase();
    const filtered = this.records.filter((record) => (language === "all" || record.language === language) && (!search || (isNumberQuery ? matchesReferenceNumber(record, search) : record.title.toLocaleLowerCase().includes(titleQuery))));
    const pageSize = input.pageSize ?? 50;
    const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
    const page = Math.min(Math.max(input.page ?? 0, 0), pageCount - 1);
    return { records: filtered.slice(page * pageSize, page * pageSize + pageSize), total: filtered.length, page, pageSize, pageCount, counts: this.counts };
  }
  getById(id: string): ReferenceCatalogRecord | undefined { return this.records.find((record) => record.id === id); }
}

export const referenceCatalogRecords = createReferenceCatalogRecords([...(czechCatalog as RawReferenceCatalogRecord[]), ...(polishCatalog as RawReferenceCatalogRecord[])]);
export const referenceCatalog = new InMemoryReferenceCatalogProvider(referenceCatalogRecords);

import type { Pool } from "pg";

export type ReferenceMelodyClassMembership = {
  songId: string;
  melodyClassId: string;
};

export interface ReferenceMelodyClassProvider {
  getClassMemberships(songIds: string[]): Promise<ReferenceMelodyClassMembership[]>;
}

export class PostgresReferenceMelodyClassProvider implements ReferenceMelodyClassProvider {
  constructor(private readonly pool: Pool) {}

  async getClassMemberships(songIds: string[]): Promise<ReferenceMelodyClassMembership[]> {
    const uniqueIds = [...new Set(songIds)].filter((songId) => /^(czech|polish):[1-9]\d*$/.test(songId));
    if (uniqueIds.length === 0) return [];
    const { rows } = await this.pool.query(
      `select reference_song_id, class_id
       from reference_song_melody_memberships
       where reference_song_id = any($1::text[])
       order by reference_song_id`,
      [uniqueIds],
    );
    return rows.map((row) => ({ songId: String(row.reference_song_id), melodyClassId: String(row.class_id) }));
  }
}

export type ReferenceMelodyEdgeEditorMode = "incomplete" | "self" | "checking" | "add" | "remove";

export function resolveReferenceMelodyEdgeEditorMode(
  firstReferenceSongId: string | undefined,
  secondReferenceSongId: string | undefined,
  edgeExists: boolean | undefined,
): ReferenceMelodyEdgeEditorMode {
  if (!firstReferenceSongId || !secondReferenceSongId) return "incomplete";
  if (firstReferenceSongId === secondReferenceSongId) return "self";
  if (edgeExists === undefined) return "checking";
  return edgeExists ? "remove" : "add";
}

export function isOutsideReferenceMelodyClass(
  referenceSongId: string,
  firstReferenceSongId: string | undefined,
  firstClassMemberIds: ReadonlySet<string> | undefined,
): boolean {
  if (!firstReferenceSongId || !firstClassMemberIds) return false;
  return !firstClassMemberIds.has(referenceSongId);
}

import type { Pool, PoolClient } from "pg";

export type ReferenceMelodyGraphSong = {
  id: string;
  language: "czech" | "polish";
  canonicalNumber: number;
};

export type ReferenceMelodyEdge = {
  songAId: string;
  songBId: string;
};

export type ReferenceMelodyPartition = {
  classBySongId: Map<string, string>;
  classCount: number;
};

type Queryable = Pick<Pool, "query"> | Pick<PoolClient, "query">;

export class ReferenceMelodyEdgeInvariantError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ReferenceMelodyEdgeInvariantError";
  }
}

function fail(message: string): never {
  throw new ReferenceMelodyEdgeInvariantError(message);
}

export function normalizeReferenceMelodyEdge(songIdA: string, songIdB: string): ReferenceMelodyEdge {
  if (!songIdA || !songIdB) fail("Reference melody edge endpoints are required.");
  if (songIdA === songIdB) fail("A Reference melody edge cannot connect a song to itself.");
  return songIdA < songIdB
    ? { songAId: songIdA, songBId: songIdB }
    : { songAId: songIdB, songBId: songIdA };
}

function compareSongIdentity(a: ReferenceMelodyGraphSong, b: ReferenceMelodyGraphSong): number {
  const languageOrder = (a.language === "czech" ? 0 : 1) - (b.language === "czech" ? 0 : 1);
  return languageOrder || a.canonicalNumber - b.canonicalNumber || a.id.localeCompare(b.id);
}

export function deriveReferenceMelodyPartition(
  songs: ReferenceMelodyGraphSong[],
  edges: ReferenceMelodyEdge[],
): ReferenceMelodyPartition {
  const byId = new Map<string, ReferenceMelodyGraphSong>();
  for (const song of songs) {
    if (byId.has(song.id)) fail(`Duplicate Reference song identity ${song.id}.`);
    byId.set(song.id, song);
  }

  const parent = new Map<string, string>();
  for (const song of songs) parent.set(song.id, song.id);

  const find = (id: string): string => {
    const current = parent.get(id);
    if (!current) fail(`Reference melody graph contains unknown song ${id}.`);
    if (current === id) return id;
    const root = find(current);
    parent.set(id, root);
    return root;
  };

  const union = (a: string, b: string) => {
    const rootA = find(a);
    const rootB = find(b);
    if (rootA !== rootB) parent.set(rootB, rootA);
  };

  const seenEdges = new Set<string>();
  for (const rawEdge of edges) {
    const edge = normalizeReferenceMelodyEdge(rawEdge.songAId, rawEdge.songBId);
    if (!byId.has(edge.songAId) || !byId.has(edge.songBId)) {
      fail(`Reference melody edge ${edge.songAId}<->${edge.songBId} points outside the Reference catalog.`);
    }
    const key = `${edge.songAId}<->${edge.songBId}`;
    if (seenEdges.has(key)) fail(`Duplicate Reference melody edge ${key}.`);
    seenEdges.add(key);
    union(edge.songAId, edge.songBId);
  }

  const membersByRoot = new Map<string, ReferenceMelodyGraphSong[]>();
  for (const song of songs) {
    const root = find(song.id);
    const members = membersByRoot.get(root) ?? [];
    members.push(song);
    membersByRoot.set(root, members);
  }

  const classBySongId = new Map<string, string>();
  for (const members of membersByRoot.values()) {
    const anchor = [...members].sort(compareSongIdentity)[0];
    const classId = `reference-melody:${anchor.id}`;
    for (const member of members) classBySongId.set(member.id, classId);
  }

  if (classBySongId.size !== songs.length) fail("Every Reference song must resolve to exactly one melody component.");
  return { classBySongId, classCount: new Set(classBySongId.values()).size };
}

export async function readReferenceMelodyGraph(db: Queryable): Promise<{
  songs: ReferenceMelodyGraphSong[];
  edges: ReferenceMelodyEdge[];
}> {
  const [songResult, edgeResult] = await Promise.all([
    db.query("select id, language, canonical_number from reference_catalog_songs order by language, canonical_number, id"),
    db.query("select song_a_id, song_b_id from reference_melody_edges order by song_a_id, song_b_id"),
  ]);
  const songs = songResult.rows.map((row) => ({
    id: String(row.id),
    language: row.language as "czech" | "polish",
    canonicalNumber: Number(row.canonical_number),
  }));
  const edges = edgeResult.rows.map((row) => ({
    songAId: String(row.song_a_id),
    songBId: String(row.song_b_id),
  }));
  return { songs, edges };
}

export async function readCurrentReferenceMelodyClassMap(db: Queryable): Promise<Map<string, string>> {
  const result = await db.query(
    "select reference_song_id, class_id from reference_song_melody_memberships order by reference_song_id",
  );
  const classBySongId = new Map<string, string>();
  for (const row of result.rows) {
    const songId = String(row.reference_song_id);
    if (classBySongId.has(songId)) fail(`Duplicate Reference melody membership for ${songId}.`);
    classBySongId.set(songId, String(row.class_id));
  }
  return classBySongId;
}

export function assertSameReferenceMelodyPartition(
  actual: Map<string, string>,
  expected: Map<string, string>,
  context = "Reference melody partition",
): void {
  if (actual.size !== expected.size) {
    fail(`${context} has ${actual.size} memberships; expected ${expected.size}.`);
  }
  for (const [songId, expectedClassId] of expected) {
    const actualClassId = actual.get(songId);
    if (actualClassId !== expectedClassId) {
      fail(`${context} mismatch for ${songId}: ${String(actualClassId)} !== ${expectedClassId}.`);
    }
  }
}

export async function assertReferenceMelodyStorageInvariant(
  db: Queryable,
  songs: ReferenceMelodyGraphSong[],
): Promise<Map<string, string>> {
  const current = await readCurrentReferenceMelodyClassMap(db);
  if (current.size !== songs.length) {
    fail(`Reference melody membership count ${current.size} does not match Reference song count ${songs.length}.`);
  }
  for (const song of songs) {
    if (!current.has(song.id)) fail(`Reference song ${song.id} has no melody membership.`);
  }

  const classResult = await db.query("select id from reference_melody_classes order by id");
  const classIds = new Set(classResult.rows.map((row) => String(row.id)));
  const referenced = new Set(current.values());
  if (classIds.size !== classResult.rows.length) fail("Duplicate Reference melody class id detected.");
  if (classIds.size !== referenced.size || [...classIds].some((id) => !referenced.has(id))) {
    fail("Reference melody classes contain an orphan or a missing referenced class.");
  }
  return current;
}

async function writeDesiredMemberships(client: Pick<PoolClient, "query">, desired: Map<string, string>): Promise<void> {
  await client.query("drop table if exists pg_temp.desired_reference_melody_memberships");
  await client.query("create temp table desired_reference_melody_memberships (reference_song_id text primary key, class_id text not null) on commit drop");
  const entries = [...desired.entries()];
  for (let start = 0; start < entries.length; start += 400) {
    const chunk = entries.slice(start, start + 400);
    const values: string[] = [];
    const params: string[] = [];
    for (const [songId, classId] of chunk) {
      const offset = values.length;
      values.push(songId, classId);
      params.push(`($${offset + 1}, $${offset + 2})`);
    }
    await client.query(
      `insert into desired_reference_melody_memberships(reference_song_id,class_id) values ${params.join(",")}`,
      values,
    );
  }
}

export async function recomputeReferenceMelodyPartition(
  client: Pick<PoolClient, "query">,
  options: { failAfterMembershipUpdate?: boolean } = {},
): Promise<{ classCount: number; membershipCount: number; changedMemberships: number }> {
  const { songs, edges } = await readReferenceMelodyGraph(client);
  await assertReferenceMelodyStorageInvariant(client, songs);
  const desired = deriveReferenceMelodyPartition(songs, edges);
  await writeDesiredMemberships(client, desired.classBySongId);

  await client.query(
    "insert into reference_melody_classes(id) select distinct class_id from desired_reference_melody_memberships on conflict do nothing",
  );
  const updated = await client.query(`
    update reference_song_melody_memberships m
       set class_id=d.class_id, updated_at=now()
      from desired_reference_melody_memberships d
     where m.reference_song_id=d.reference_song_id
       and m.class_id<>d.class_id
    returning m.reference_song_id
  `);
  if (options.failAfterMembershipUpdate) throw new Error("Injected Reference melody recompute failure after membership update.");

  await client.query(
    "delete from reference_melody_classes c where not exists (select 1 from reference_song_melody_memberships m where m.class_id=c.id)",
  );

  const actual = await assertReferenceMelodyStorageInvariant(client, songs);
  assertSameReferenceMelodyPartition(actual, desired.classBySongId, "Recomputed Reference melody partition");
  return {
    classCount: desired.classCount,
    membershipCount: desired.classBySongId.size,
    changedMemberships: updated.rows.length,
  };
}
